INSERT INTO `products` (`id`, `name`, `slug`, `description`, `price`, `compare_price`, `stock_quantity`, `sku`, `category_id`, `images`, `is_active`, `is_featured`, `brand`, `specifications`, `created_at`, `updated_at`) VALUES (1,'Helmet','Helmet','<p>full face</p>',75.00,100.00,85,'HEL-001',1,'[\"products/01KS4B3W0QVMY4CB2P2D99PDD6.jpg\"]',1,1,'KYT','{\"Size\": \"S/M/XL\", \"Brand\": \"KYT\", \"Color\": \"Black and white\", \"Years\": \"2026\"}','2026-05-20 20:19:48','2026-05-21 23:03:23'),(2,'LED Light','led-light','<p>RGB full light</p>',15.00,25.00,18,'DMX-V1',2,'[\"products/01KS4B4TXCE4VV5K76BHN00V0A.jpg\"]',1,1,'DMX','{\"BOT\": \"2 Output\", \"From\": \"Indonesia \", \"Brand\": \"DMX\"}','2026-05-20 20:34:14','2026-05-21 21:17:41'),(3,'Gloves','gloves','<p>The best gloves for you!!!</p>',0.01,5.00,16,'KYT-G-001',3,'[\"products/01KS4B5EMX2D4PM221EN5EXQ3R.jpg\"]',1,1,'KYT','{\"Brand\": \"KYT\", \"Color\": \"White and blue\"}','2026-05-20 20:38:18','2026-05-26 10:10:07'),(4,'RCB Break','rcb-break','<p>RCB break</p>',22.00,25.00,100,'RCB-001',2,'[\"products/01KS5X9F9C5CHEBG2SRR7TF0DS.jpg\"]',1,1,'RCB','{\"Color\": \"Black and red\", \"Model\": \"RCB\", \"Sensor\": \"2 sensor, left and right\"}','2026-05-21 11:38:13','2026-05-22 09:12:03'),(5,'Stickers','stickers','<p>Stickers for bikes</p>',3.50,5.00,18,'STIKERS-001',3,'[\"products/01KS87XCN5XC4XV3714B9AP6BG.jpg\"]',1,1,'Stickers','{\"Album\": \"30 Stickers\", \"Color\": \"Colorful\", \"Made in\": \"Cambodia\"}','2026-05-22 09:22:21','2026-05-23 10:40:22'),(6,'KYT Helmet','kyt-helmet','<p>Full face</p>',125.00,150.00,66,'HEL-002',1,'[\"products/01KS88B05HXJBPHD00W67DVMSD.jpg\"]',1,1,'KYT','{\"Size\": \"S/M/L/XL\", \"Brand\": \"KYT\", \"Color\": \"Black and White\", \"Glasses\": \"2 Black and white\"}','2026-05-22 09:29:47','2026-05-25 19:45:43'),(7,'MFZ Caliper','mfz-caliper','<blockquote><p>Upgrade your machine’s stopping power with the <strong>MFZ Racing High-Performance Radial Brake Caliper</strong>. Engineered explicitly for demanding track setups, performance scooters (like XMAX, Forza), and custom sportbikes, this masterfully crafted component replaces weak factory setups with absolute precision.</p><p>Machined flawlessly from a single block of <strong>A7075 Super Duralumin alloy</strong>, it maximizes structural rigidity under extreme clamping loads while maintaining a lightweight profile. The exterior body features integrated, deep aggressive cooling fins designed to rapidly dissipate heat, eliminating brake fade during hard tracking sessions. Fitted with premium anodized protection, striking red branding accents, and integrated pressure bleeders, it delivers elite-tier braking modulation at an exceptional value.</p></blockquote>',75.00,100.00,51,'MFZ-4B',2,'[\"products/01KS89RNN3ZCNJK7AE0PCA89NM.jpg\"]',1,1,'MFZ Racing','{\"Brand\": \"MFZ Racing\", \"Material\": \"CNC-Machined Billet Aluminum Alloy (A7075 Super Duralumin)\", \"Mounting Type\": \"Radial Mount\", \"Piston Configuration\": \"4-Piston Setup\", \"Available Mounting Pitch\": \"100mm / 108mm (Standard Radial Universal)\"}','2026-05-22 09:54:43','2026-06-03 18:31:17'),(8,'KURADO Premium Front Shock Absorber Assembly (5cm Lower)','kurado-premium-front-shock-absorber-assembly-5cm-lower','<p>Upgrade your ride with the KURADO Premium Front Shock Absorber Assembly. Featuring a striking, high-polished anodized gold inner tube finish paired with durable satin black lowers, these forks deliver a premium sport aesthetic and high-performance dampening control.</p><p>This model is engineered to sit 5 cm lower than the original stock (Zin) height, making it the perfect choice for riders looking to achieve a clean, aggressive, low-down stance while maintaining excellent stability and handling on the road.</p><p>Designed as a direct factory replacement, it comes pre-sealed and ready to install with factory-integrated heavy-duty mounting points for your front brake caliper and fender.</p><p>Key Features:</p><p>- Premium Custom Look: High-polished gold stanchions with satin black sliders.</p><p>- Low-Down Stance: 5 cm lower than OEM (Zin) height for a sporty, custom look.</p><p>- Direct Fitment: Features built-in caliper and fender brackets for a hassle-free install.</p><p>- High-Grade Performance: Advanced internal oil seals prevent leaks and ensure a smooth, stable ride.</p><p>- Authenticity Guaranteed: Includes genuine Kurado holographic seal and scannable verification code on the packaging.</p><p>ដំឡើងស៊េរីម៉ូតូរបស់អ្នកជាមួយបូមមុខអាជីព KURADO Premium Front Shock Absorber Assembly។ ជាមួយការរចនាពណ៌មាសភ្លឺរលោង (Anodized Gold) ផ្នែកខាងលើ និងពណ៌ខ្មៅគ្រើម (Satin Black) ផ្នែកខាងក្រោម ផ្តល់នូវប្រណីតភាព និងភាពទាក់ទាញបំផុត។</p><p>បូមម៉ូដែលនេះត្រូវបានកែច្នៃឲ្យមានកម្ពស់ទាបជាងសំបកស៊ីនហ្ស៊ីន (Zin) 5 cm ដែលជាជម្រើសដ៏ល្អឥតខ្ចោះសម្រាប់អ្នកដែលចូលចិត្តលេងម៉ូតូស្ទីលទាប (Low-down style) ជួយឲ្យម៉ូតូមានលំនឹងល្អ និងរាងស្ព័រស្រស់ស្អាត។</p><p>លក្ខណៈពិសេស៖</p><p>- កម្ពស់ទាបជាងស៊ីនហ្ស៊ីន (Zin) 5 cm ផ្តល់រាងទាប បែបស្ព័រ និងលំនឹងរឹងមាំ</p><p>- ពណ៌មាសលាយខ្មៅស្អាតប្លែក បែប Premium Custom Look</p><p>- មានជើងចាប់ហ្វ្រាំងឌីស និងជើងចាប់កាងកាត់ភក់មកស្រាប់ (Direct OEM Replacement)</p><p>- ក្រវិលប្រេងកម្រិតខ្ពស់ ការពារការលេចជ្រាបប្រេង និងធានាភាពទន់ភ្លន់ពេលបើកបរ</p><p>- ផលិតផលសុទ្ធ 100% មានស្ទីកគ័រហូឡូក្រាម និង QR Code បញ្ជាក់ពីគុណភាពនៅលើប្រអប់</p>',25.00,45.00,40,'KURADO-5CM',2,'[\"products/01KS9R2T9WNBPBP7HEDRFYKCY2.jpg\"]',1,0,'KURADO','{\"Brand\": \"KURADO\", \"Style\": \"Low-down Stance / Sporty Look\", \"height\": \"5cm lower than OEM (ទាបជាងស៊ីន 5 សង់ទីម៉ែត្រ)\", \"Features\": \"Pre-sealed, Includes Caliper & Fender Mounts\", \"Placement\": \"Front (Left & Right Pair)\", \"Installation\": \"Direct OEM Replacement\", \"Product Type\": \"Front Shock Absorber Assembly\", \"Color / Finish\": \"Gold Inner Tubes / Satin Black Lowers\"}','2026-05-22 23:24:10','2026-05-22 23:45:08'),(9,'HT Racing CNC Aluminum Radiator Guard for Honda Click / Vario 125/150','ht-racing-cnc-aluminum-radiator-guard-for-honda-click-vario-125150','<p>Protect and stylize your bike&#039;s cooling system with the HT Racing CNC Aluminum Radiator Guard. Precision-engineered specifically for Honda Click and Vario 125/150 models, this premium shield protects your delicate radiator fins from road debris, rocks, and damage without restricting airflow.</p><p>Cut from high-grade aluminum with a brilliant silver finish, it features aggressive diagonal slots for a clean, custom racing aesthetic.</p><p>Key Features:</p><p>- Robust Protection: Shields your radiator core from costly stone puncture damage.</p><p>- Premium CNC Build: Light, durable, and rust-resistant billet aluminum.</p><p>- Complete Kit: Comes with the necessary mounting bolts and metal spacers for a quick install.</p><p>- Perfect Fitment: Tailored precisely for Honda Click &amp; Vario 125/150.</p><p>ការពារ និងបង្កើនសម្រស់ប្រព័ន្ធស្អំទឹកម៉ូតូរបស់អ្នកជាមួយ សំណាញ់ការពារធុងទឹក CNC ពីប្រេន HT Racing។ ត្រូវបានរចនាឡើងយ៉ាងច្បាស់លាស់សម្រាប់ម៉ូដែល Honda Click និង Vario ស៊េរី 125/150 ជួយការពារធុងទឹកពីការខ្ទាតដុំថ្ម ឬកម្ទេចកំទីផ្សេងៗ មិនឱ្យខូចខាតសរសៃញែកធុងទឹក ដោយមិនបង្កការស្ទះខ្យល់ឡើយ។</p><p>ផលិតពីអាលុយមីញ៉ូមប្រភេទក្រាស់ (CNC Aluminum) ពណ៌ប្រាក់ភ្លឺរលោង រឹងមាំមិនងាយច្រែះ និងមានរន្ធឆ្នូតស្អាត បែបស្ព័រ ទាក់ទាញ។</p><p>លក្ខណៈពិសេស៖</p><p>- ការពារខ្ពស់៖ ការពារធុងទឹកពីការធ្លាយ ឬវៀចសរសៃញែកដោយសារការខ្ទាតថ្ម</p><p>- គុណភាព Premium CNC៖ ផលិតពីអាលុយមីញ៉ូមម៉ាស៊ីនកាត់ ស្រាល ក្រាស់ និងធន់ខ្លាំង</p><p>- មានគ្រឿងផ្គុំស្រាប់៖ មកជាមួយខ្ចៅ និងតម្រង់ (Spacers) ងាយស្រួលដំឡើងដោយខ្លួនឯង</p><p>- ត្រូវចំស៊េរី៖ សម្រាប់ប្រើប្រាស់ត្រូវចំពោះ Honda Click &amp; Vario 125/150 តែម្តង</p>',15.00,18.00,13,'HT-RACING',2,'[\"products/01KS9S7BXM02XCS6KEBJVJY41K.jpg\"]',1,1,'HT Racing','{\"Brand\": \"HT Racing\", \"Color\": \"Silver / Chrome Finish\", \"Origin\": \"Made in Vietnam (Sản xuất tại Việt Nam)\", \"Material\": \"High-Grade CNC Billet Aluminum\", \"Product Type\": \"Radiator Guard / Cover (សំណាញ់ធុងទឹក)\", \"Compatibility\": \"Honda Click 125i / 150i, Honda Vario 125 / 150\", \"Included Hardware\": \"3x Mounting Bolts & Spacer Sleeves\"}','2026-05-22 23:44:08','2026-05-23 23:11:25');
